css:
.fx-sp{width:min(860px,100%);display:grid;gap:1.8em;text-align:center}
.fx-sp h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-sp .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1em}
.fx-sp .cell{display:grid;gap:1em;justify-items:center;padding:1.8em 1em 1.2em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-sp .cell>span{font-size:.82em;opacity:.6}
.fx-sp .u{position:relative;width:3em;height:3em;display:grid;place-items:center}
.fx-sp .u-ring i{position:absolute;inset:0;border-radius:50%;border:3px solid color-mix(in srgb,var(--primary) 18%,transparent);border-top-color:var(--primary);animation:fxsps calc(.9s/var(--speed)) linear infinite}
.fx-sp .u-dual i{position:absolute;inset:0;border-radius:50%;border:3px solid transparent;border-top-color:var(--primary);border-bottom-color:var(--primary);animation:fxsps calc(1.1s/var(--speed)) linear infinite}
.fx-sp .u-dual i+i{inset:.5em;border-top-color:var(--accent);border-bottom-color:var(--accent);animation-direction:reverse;animation-duration:calc(.8s/var(--speed))}
.fx-sp .u-dots{display:flex;gap:.35em;align-items:center}
.fx-sp .u-dots i{width:.7em;height:.7em;border-radius:50%;background:var(--primary);animation:fxspb calc(1s/var(--speed)) ease-in-out infinite}
.fx-sp .u-dots i:nth-child(2){animation-delay:calc(.15s/var(--speed));background:color-mix(in srgb,var(--primary) 50%,var(--accent))}.fx-sp .u-dots i:nth-child(3){animation-delay:calc(.3s/var(--speed));background:var(--accent)}
.fx-sp .u-bars{display:flex;gap:.22em;align-items:center}
.fx-sp .u-bars i{width:.3em;height:2.2em;border-radius:99px;background:var(--primary);animation:fxspv calc(1s/var(--speed)) ease-in-out infinite}
.fx-sp .u-bars i:nth-child(2){animation-delay:calc(.1s/var(--speed))}.fx-sp .u-bars i:nth-child(3){animation-delay:calc(.2s/var(--speed));background:var(--accent)}.fx-sp .u-bars i:nth-child(4){animation-delay:calc(.3s/var(--speed))}.fx-sp .u-bars i:nth-child(5){animation-delay:calc(.4s/var(--speed))}
.fx-sp .u-pulse i{position:absolute;inset:0;border-radius:50%;border:2px solid var(--primary);animation:fxspp calc(1.6s/var(--speed)) ease-out infinite}
.fx-sp .u-pulse i+i{border-color:var(--accent);animation-delay:calc(.8s/var(--speed))}
.fx-sp .u-sweep i{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,transparent 0,var(--accent) 100%);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 4px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 4px),#000 calc(100% - 3px));animation:fxsps calc(1s/var(--speed)) linear infinite}
.fx-sp .btnrow{display:flex;justify-content:center;gap:1em;flex-wrap:wrap}
.fx-sp .btn{display:inline-flex;align-items:center;gap:.7em;padding:.9em 1.6em;border-radius:var(--radius);border:0;background:var(--primary);color:var(--on-primary);font:700 .95em var(--font-body);cursor:progress;opacity:.92}
.fx-sp .btn .mini{width:1.1em;height:1.1em;border-radius:50%;border:2px solid color-mix(in srgb,var(--on-primary) 30%,transparent);border-top-color:var(--on-primary);animation:fxsps calc(.8s/var(--speed)) linear infinite}
@keyframes fxsps{to{transform:rotate(360deg)}}
@keyframes fxspb{0%,80%,100%{transform:translateY(0) scale(.8);opacity:.6}40%{transform:translateY(-.7em) scale(1);opacity:1}}
@keyframes fxspv{0%,100%{transform:scaleY(.3)}50%{transform:scaleY(1)}}
@keyframes fxspp{from{transform:scale(.2);opacity:1}to{transform:scale(1);opacity:0}}
@keyframes fxspfade{50%{opacity:.35}}
@media(max-width:560px){.fx-sp .grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(prefers-reduced-motion:reduce){.fx-sp .u *,.fx-sp .btn .mini{animation:none!important}.fx-sp .u,.fx-sp .btn .mini{animation:fxspfade 1.8s ease-in-out infinite!important}.fx-sp .u-pulse i{transform:scale(.7)}}
